const dateLabel = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('vi-VN', {weekday:'long',day:'2-digit',month:'long',year:'numeric'})
const weekDates = (date: string) => Array.from({length:7},(_,i)=>{const d=new Date(`${date}T12:00:00`);const day=d.getDay();d.setDate(d.getDate()-(day===0?6:day-1)+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`})
const compactDateLabel = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit'})
const weekdayLabel = (date: string) => {
  const label=new Date(`${date}T12:00:00`).toLocaleDateString('vi-VN',{weekday:'long'})
  return label.charAt(0).toLocaleUpperCase('vi-VN')+label.slice(1)
}
function Badge({ children, amber = false }: { children: ReactNode; amber?: boolean }) { return <span className={`badge ${amber ? 'amber' : ''}`}>{amber ? <Clock3 size={12}/> : <CheckCheck size={13}/>} {children}</span> }
function Dialog({ title, children, close }: {title:string;children:ReactNode;close:()=>void}) {
  const ref = useRef<HTMLDialogElement>(null)
  useEffect(() => { const el = ref.current; el?.showModal(); return () => el?.close() }, [])
  return <dialog aria-label={title} ref={ref} onCancel={close} onClick={e => { if (e.target === e.currentTarget) close() }}><div className="dialog-head"><h2>{title}</h2><button className="icon-button" aria-label="Đóng" onClick={close}><X/></button></div>{children}</dialog>
}
function Timeline({ data, compact = false }: {data:DayData;compact?:boolean}) { return <div className={`timeline ${compact ? 'compact' : ''}`}>{data.events.map((event,i) => <div className="timeline-item" key={event.status}><span className={`timeline-node ${event.confirmed ? 'done':'pending'}`}>{event.confirmed ? <Check size={14}/> : <Clock3 size={14}/>}</span><div><div className="timeline-title"><strong>{event.label}</strong><time>{event.time}</time></div><p>{event.actor}</p><span className={event.confirmed ? 'confirmed-text' : 'pending-text'}>{event.confirmed ? 'Đã xác nhận' : 'Đã báo cáo · Chờ BGH xác nhận'}</span>{!compact && <>{event.photos.length>0?<div className="timeline-photos" aria-label={`Ảnh thực tế mốc ${event.label}`}>{event.photos.map((photo,photoIndex)=><img key={photoIndex} src={photo} alt={`Ảnh thực tế mốc ${event.label} ${photoIndex+1}`}/>)}</div>:<p className="timeline-photo-state">{event.hasReportedPhotos?'Ảnh thực tế đang chờ BGH duyệt công khai':'Chưa có ảnh thực tế được công khai'}</p>}<p className="muted">{demo ? `Bản ghi DEMO · Mốc ${i + 1}` : `Mốc ${i + 1}`}</p></>}</div></div>)}</div> }
type WeeklyMenuEntry = { date: string; data: DayData }
