    <header className="weekly-menu-header"><div><div className="section-kicker">TỔNG QUAN 7 NGÀY</div><h2 id="weekly-menu-title">Thực đơn cả tuần</h2><p>{compactDateLabel(dates[0]!)} – {compactDateLabel(dates.at(-1)!)} · {demo?'Dữ liệu minh họa':'Thông tin đã công khai'}</p></div><div className="weekly-menu-navigation"><button className="icon-button" aria-label="Xem thực đơn tuần trước" onClick={onPrevious}><ChevronLeft/></button><span>Tuần này</span><button className="icon-button" aria-label="Xem thực đơn tuần sau" onClick={onNext}><ChevronRight/></button></div></header>
